    MatOut m;
    double D = E*t*t*t/(12.0*(1.0-nu*nu));
    m.G11 = D; m.G22 = D; m.G33 = D*(1.0-nu)/2.0;
    m.G12 = nu*D; m.G13 = 0.0; m.G23 = 0.0;
    return m;
