// GMMATD: C = op(A)*op(B). A is ma x na, B is mb x nb.
// transa=1 -> A^T, transb=1 -> B^T
MatrixXd gmmatd(const MatrixXd& A, int transa, const MatrixXd& B, int transb) {
    MatrixXd At = (transa==1) ? A.transpose() : A;
    MatrixXd Bt = (transb==1) ? B.transpose() : B;
    return At * Bt;
